import { inflateSync } from 'node:zlib'
import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'

/**
 * Cross-implementation check: dart:io must produce zlib-format deflate streams that
 * node:zlib decodes with the same rolling dictionary. The vectors are
 * generated by dsh-go's `packages/dsh_remote/bin/gen_dshz_dart_vectors.dart`
 * (node vectors in, dart-packed vectors out); the fixture lives next to this
 * test when regenerated. Synthetic filler only — no real communication.
 */
describe('DSHZ dart:io golden vectors', () => {
  const fixture = join(import.meta.dirname, 'fixtures', 'dshz-dart-golden.json')

  it('decodes dart-produced packed bytes', { skip: !existsSync(fixture) && 'regenerate with gen_dshz_dart_vectors.dart' }, () => {
    const cases = JSON.parse(readFileSync(fixture, 'utf8')) as Array<{
      name: string
      plainB64: string
      dictionaryB64: string
      packedB64: string
    }>
    expect(cases.length).toBeGreaterThan(0)
    for (const testCase of cases) {
      const dictionary = Buffer.from(testCase.dictionaryB64, 'base64')
      const restored = inflateSync(Buffer.from(testCase.packedB64, 'base64'),
        dictionary.byteLength > 0 ? { dictionary } : {})
      expect(Buffer.compare(restored, Buffer.from(testCase.plainB64, 'base64'))).toBe(0)
    }
  })
})
